def check_equation(x, y, z):
    # Check if x^3 + y^3 + z^3 - x^2*y^2*z^2 = 0
    lhs = x**3 + y**3 + z**3
    rhs = x**2 * y**2 * z**2
    return lhs == rhs

solutions = []
Z_max = 10

# Iterate through all possible triples (x, y, z) such that 1 <= x <= y <= z <= Z_max
for x in range(1, Z_max + 1):
    for y in range(x, Z_max + 1):
        for z in range(y, Z_max + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("Solutions found:")
for sol in solutions:
    print(sol)

print(f"\nTotal solutions found: {len(solutions)}")
